645	// storedDuplicateID reports the first batch id held by two records of the
646	// registry as handed in, scanning in stored order: Batch is that id, First
647	// the 1-based position of its first record and Second the position of its
648	// earliest repeat. It returns nil when every stored id is unique. Ids compare
649	// byte for byte, so "B1", "b1" and " B1 " are different ids.
650	//
651	// Register and Import run this check because a Go caller may hand them a
652	// Registry assembled directly — without Load — whose records already share an
653	// id. Neither entry point may then treat one of those records as the id's
654	// record (confirming a repeat against it, conflicting with it or appending
655	// next to it), and neither may repair the registry by dropping or merging a
656	// record: the only honest answer is the DuplicateIDError Load would have
657	// raised.
658	func storedDuplicateID(reg *Registry) *DuplicateIDError {
659		seen := make(map[string]int, len(reg.Batches))
660		for i, b := range reg.Batches {
661			pos := i + 1
662			if first, dup := seen[b.Batch]; dup {
663				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
664			}
665			seen[b.Batch] = pos
666		}
667		return nil
668	}
669	
670	func validate(reg *Registry) error {
671		seen := make(map[string]int, len(reg.Batches))
672		for i, b := range reg.Batches {
673			pos := i + 1
674			if b.Batch == "" || b.Product == "" || b.Unit == "" {
675				return fmt.Errorf("batches record %d (batch %q): batch, product and unit must all be non-empty", pos, b.Batch)
676			}
677			if b.Quantity <= 0 {
678				return fmt.Errorf("batches record %d (batch %q): quantity must be a positive integer", pos, b.Batch)
679			}
680			if first, dup := seen[b.Batch]; dup {
681				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
682			}
683			seen[b.Batch] = pos
684		}
685		return nil
686	}
