688	// ManifestRecordError reports a manifest record that is structurally invalid
689	// or carries a quantity outside the accepted range. Position is the record's
690	// 1-based position in the manifest.
691	type ManifestRecordError struct {
692		Position int
693		Batch    string // normalized batch id when available, otherwise ""
694		Reason   string
695	}
696	
697	func (e *ManifestRecordError) Error() string {
698		if e.Batch != "" {
699			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
700		}
701		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
702	}
