704	// ManifestConflictError reports that a manifest record disagrees with the
705	// record already registered, or introduced earlier in the same manifest,
706	// under the same batch id. Position is the record's 1-based position in the
707	// manifest and Fields lists every differing member among "product",
708	// "quantity" and "unit" in that order.
709	type ManifestConflictError struct {
710		Position int
711		Batch    string
712		Fields   []string
713		Source   string // "registry" or "manifest"
714		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
715	}
716	
717	func (e *ManifestConflictError) Error() string {
718		if e.Source == "manifest" {
719			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
720				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
721		}
722		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
723			e.Position, e.Batch, strings.Join(e.Fields, ", "))
724	}
