726	// ParseManifest decodes data as a non-empty JSON array holding exactly the
727	// four required fields batch, product, quantity and unit per element. The
728	// three text fields must be JSON strings that are not blank after trimming;
729	// quantity must be a JSON integer (no strings, fractions or exponents) in
730	// the range 1..MaxQuantity. An empty file, empty array, non-array document
731	// or any malformed record is rejected. The manifest bytes are never written.
732	func ParseManifest(data []byte) ([]Input, error) {
733		trimmed := bytes.TrimSpace(data)
734		if len(trimmed) == 0 {
735			return nil, errors.New("manifest file is empty")
736		}
737		if trimmed[0] != '[' {
738			return nil, errors.New("manifest must be a non-empty JSON array of records")
739		}
740	
741		var elems []json.RawMessage
742		dec := json.NewDecoder(bytes.NewReader(data))
743		if err := dec.Decode(&elems); err != nil {
744			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
745		}
746		var extra json.RawMessage
747		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
748			if err == nil {
749				return nil, errors.New("manifest has unexpected data after the array")
750			}
751			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
752		}
753		if len(elems) == 0 {
754			return nil, errors.New("manifest must contain at least one record")
755		}
756	
757		inputs := make([]Input, 0, len(elems))
758		for i, raw := range elems {
759			pos := i + 1
760			in, err := parseManifestRecord(raw)
761			if err != nil {
762				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
763			}
764			inputs = append(inputs, in)
765		}
766		return inputs, nil
767	}
768	
769	// batchRecordFields are the only members a batch record may carry, in the
770	// registry file and in an import manifest alike.
771	var batchRecordFields = map[string]struct{}{
772		"batch": {}, "product": {}, "quantity": {}, "unit": {},
773	}
774	
775	// parseManifestRecord validates one manifest element: it must be a JSON
776	// object with exactly the four required keys, text fields as non-blank,
777	// valid UTF-8 strings and quantity as a strict JSON integer. The members
778	// are scanned with parseObjectFields (strict key decoding, duplicates kept
779	// visible) rather than a lenient map unmarshal, so malformed key or value
780	// bytes cannot be silently replaced with U+FFFD. Whatever makes the record
781	// fail — an unknown, duplicated or case-mismatched field included — the
782	// returned Input carries the normalized batch id whenever exactly one
783	// "batch" member holds valid, non-blank text, so the caller can name the
784	// batch in the error; otherwise it stays empty.
785	//
786	// The structural rules are shared with parseRegistryRecord; this source's
787	// own choices are: member-name anomalies are reported in source order
788	// (unknown and duplicate carry equal weight), text is trimmed and must stay
789	// non-empty, and reasons use manifest wording (including *EncodingError for
790	// malformed text). A member name that cannot be decoded fails the record
791	// with keyEncodingReason before the source-order anomaly scan — the
792	// U+FFFD-substituted text is never judged as an unknown or duplicate name.
793	func parseManifestRecord(raw json.RawMessage) (Input, error) {
794		var in Input
795		members, badKey, err := parseObjectFields(raw)
796		if err != nil {
797			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
798		}
799		// Attach the batch id to whatever error this record raises, but only when
800		// it is unambiguous: exactly one "batch" member (compared after JSON key
801		// decoding, so an escaped respelling counts as the same field) carrying a
802		// JSON string whose decoded text is valid UTF-8 and non-blank once
803		// trimmed. A missing, duplicated, mistyped, blank or malformed "batch"
804		// member leaves the id out — never a U+FFFD substitution, and never one
805		// of two duplicate values picked arbitrarily, even when both are equal.
806		// Where the "batch" member sits relative to the offending field does not
807		// matter.
808		in.Batch = unambiguousBatchID(members, textTrimmed)
809	
810		// A member name that cannot be decoded is a name-encoding problem, never
811		// an unknown field: the substituted text is not a real name.
812		if badKey {
813			return in, errors.New(keyEncodingReason)
814		}
815	
816		// Manifest member-name problems are reported in source order: the first
817		// unknown name or first repeat fails the record.
818		switch fault := checkRecordMembers(members, false); fault.kind {
819		case faultUnknown:
820			return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", fault.field)
821		case faultDuplicate:
822			return in, fmt.Errorf("record lists field %q more than once", fault.field)
823		}
824	
825		textField := func(name string) (string, error) {
826			rawValue, found := findField(members, name)
827			value, problem, cause := decodeRecordText(rawValue, found, textTrimmed)
828			switch problem {
829			case fieldMissing:
830				return "", fmt.Errorf("missing required field %q", name)
831			case fieldNotString:
832				return "", fmt.Errorf("field %q must be a JSON string", name)
833			case fieldEncoding:
834				return "", &EncodingError{Field: name}
835			case fieldBlank:
836				return "", fmt.Errorf("field %q must not be blank: %w", name, cause)
837			}
838			return value, nil
839		}
840	
841		in.Batch, err = textField("batch")
842		if err != nil {
843			return in, err
844		}
845		in.Product, err = textField("product")
846		if err != nil {
847			return in, err
848		}
849		in.Unit, err = textField("unit")
850		if err != nil {
851			return in, err
852		}
853		quantityRaw, ok := findField(members, "quantity")
854		if !ok {
855			return in, errors.New("missing required field \"quantity\"")
856		}
857		in.Quantity, err = manifestQuantityError(bytes.TrimSpace(quantityRaw))
858		if err != nil {
859			return in, err
860		}
861		return in, nil
862	}
863	
864	// ImportResult is one entry of an Import outcome: the normalized record in
865	// manifest order plus whether it was newly created or already present.
866	type ImportResult struct {
867		Batch   Batch
868		Created bool
869	}
870	
871	// validateManifestInput applies the same effective-value rules to one
872	// directly submitted record that Register enforces for single entries and
873	// parseManifestRecord enforces for file records: the three text fields must
874	// be valid UTF-8 and must not be empty strings, and quantity must lie in
875	// 1..MaxQuantity. Text is checked verbatim — direct submissions get no
876	// whitespace trimming or case folding (the command-line entry normalizes
877	// before constructing the Input), so whitespace-only text is accepted as
878	// ordinary non-empty text. pos is the record's 1-based position in this
879	// submission. The returned *ManifestRecordError names the offending field
880	// in its reason and cites the batch id only when that id is itself
881	// non-empty, valid UTF-8 text; it is never invented or substituted when the
882	// batch field is empty or malformed.
883	func validateManifestInput(in Input, pos int) error {
884		// batchID is "" whenever the batch field itself is empty or malformed, so
885		// it is safe to attach it to whichever error follows.
886		batchID := safeBatchIDForError(in.Batch)
887		// Import reports an encoding problem anywhere in the three text fields
888		// before any empty-text problem; quantity problems come after both.
889		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
890		if issue, bad := firstTextIssue(issues, textEncoding); bad {
891			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: (&EncodingError{Field: issue.field}).Error()}
892		}
893		if issue, bad := firstTextIssue(issues, textEmpty); bad {
894			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: fmt.Sprintf("field %q must not be empty", issue.field)}
895		}
896		switch classifyDecodedQuantity(in.Quantity) {
897		case decodedQtyNotPositive:
898			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: `field "quantity" must be greater than zero`}
899		case decodedQtyAboveMax:
900			return &ManifestRecordError{Position: pos, Batch: batchID,
901				Reason: fmt.Sprintf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)}
902		}
903		return nil
904	}
905	
906	// Import validates every record of inputs before appending anything: the
907	// whole manifest fails if any record carries invalid UTF-8, an empty text
908	// field or a quantity outside 1..MaxQuantity — whether its batch id is new,
909	// already stored or seen earlier in this submission — or if any record
910	// conflicts with a stored record or with an earlier manifest record, and reg
911	// is left untouched on error. A reg that already holds two records under one
912	// batch id (only possible when it was assembled directly, since Load refuses
913	// such files) likewise fails the whole submission with a *DuplicateIDError
914	// naming the id and the two 1-based stored positions — checked after the
915	// version and record validations above, before any create, duplicate
916	// confirmation or conflict, and leaving reg exactly as handed in. Directly
917	// submitted text is kept verbatim. New
918	// batch ids are appended in first-occurrence order; an id already stored or
919	// introduced earlier in the same manifest is confirmed as a duplicate only
920	// when product, quantity and unit all match. Results come back in manifest
921	// order; Created is false for duplicates.
922	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
923		if reg.Version != FormatVersion {
924			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
925		}
926		if len(inputs) == 0 {
927			return nil, errors.New("manifest must contain at least one record")
928		}
929		// Reject malformed text and non-effective values before touching
930		// anything; this covers records handed in directly by Go callers the
931		// same way ParseManifest covers file records, so a blank text field or a
932		// non-positive quantity can never reach the new/duplicate/conflict logic
933		// below and end up in a file the reader would refuse. Text is checked
934		// verbatim: direct submissions get no trimming or case folding (only the
935		// command-line entry normalizes, before building the Input).
936		for i, in := range inputs {
937			if err := validateManifestInput(in, i+1); err != nil {
938				return nil, err
939			}
940		}
941	
942		// A registry that already holds two records under one id — possible only
943		// when the caller assembled it directly, since Load refuses such files —
944		// rejects the whole submission before any create, duplicate confirmation
945		// or conflict is weighed: the existing records are ambiguous and Import
946		// must neither pick one of them as the id's record nor repair the
947		// registry on its own.
948		if dup := storedDuplicateID(reg); dup != nil {
949			return nil, dup
950		}
951	
952		// Work on a copy: a rejected manifest must never partially land in reg.
953		working := append([]Batch(nil), reg.Batches...)
954		indexByID := make(map[string]int, len(working))
955		for i, b := range working {
956			indexByID[b.Batch] = i
957		}
958		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
959	
960		out := make([]ImportResult, len(inputs))
961		for i, in := range inputs {
962			pos := i + 1
963			if idx, known := indexByID[in.Batch]; known {
964				existing := working[idx]
965				diffs := diffFields(existing, in)
966				if len(diffs) > 0 {
967					if prev, inManifest := firstPos[in.Batch]; inManifest {
968						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
969					}
970					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
971				}
972				out[i] = ImportResult{Batch: existing, Created: false}
973				continue
974			}
975			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
976			working = append(working, b)
977			indexByID[in.Batch] = len(working) - 1
978			firstPos[in.Batch] = pos
979			out[i] = ImportResult{Batch: b, Created: true}
980		}
981	
982		reg.Batches = working
983		return out, nil
984	}
985	
986	// diffFields lists the members of product, quantity and unit in which in
987	// differs from existing, in that fixed order.
988	func diffFields(existing Batch, in Input) []string {
989		var diffs []string
990		if existing.Product != in.Product {
991			diffs = append(diffs, "product")
992		}
993		if existing.Quantity != in.Quantity {
994			diffs = append(diffs, "quantity")
995		}
996		if existing.Unit != in.Unit {
997			diffs = append(diffs, "unit")
998		}
999		return diffs
1000	}
1001	
1002	// Register adds in to reg, or confirms the identical record already stored
1003	// under the same batch id. A batch id held by a record differing in product,
1004	// quantity or unit produces a *ConflictError and leaves reg untouched. A reg
1005	// that already holds two records under one batch id (only possible when it
1006	// was assembled directly, since Load refuses such files) produces a
1007	// *DuplicateIDError naming the id and the two 1-based stored positions —
1008	// reported after the version and input validations above, before any stored
1009	// record is consulted, and leaving reg exactly as handed in. The zero Outcome
1010	// is returned together with the error.
1011	func Register(reg *Registry, in Input) (Outcome, error) {
1012		if reg.Version != FormatVersion {
1013			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
1014		}
1015		// Register reports any empty text field before any encoding problem;
1016		// quantity problems come after both.
1017		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
1018		if _, bad := firstTextIssue(issues, textEmpty); bad {
1019			return Outcome{}, errors.New("batch, product and unit must be non-empty")
1020		}
1021		if issue, bad := firstTextIssue(issues, textEncoding); bad {
1022			return Outcome{}, &EncodingError{Field: issue.field}
1023		}
1024		if !quantityInRange(in.Quantity) {
1025			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
1026		}
1027		// A registry already holding two records under one id — possible only
1028		// when the caller assembled it directly, since Load refuses such files —
1029		// rejects the registration before the stored records are consulted: no
1030		// record may be picked as the id's record for a confirmation or a
1031		// conflict, and the ambiguous records are never merged or pruned.
1032		if dup := storedDuplicateID(reg); dup != nil {
1033			return Outcome{}, dup
1034		}
1035		for _, b := range reg.Batches {
1036			if b.Batch != in.Batch {
1037				continue
1038			}
1039			if diffs := diffFields(b, in); len(diffs) > 0 {
1040				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
1041			}
1042			return Outcome{Batch: b, Created: false}, nil
1043		}
1044		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
1045		reg.Batches = append(reg.Batches, b)
1046		return Outcome{Batch: b, Created: true}, nil
1047	}
1048	
1049	// validateForSave checks every record of reg against the rules Load enforces,
1050	// so a hand-assembled registry cannot be persisted in a shape the reader
1051	// would refuse. Records are checked in order and the first violation is
1052	// reported as a *FormatError naming the 1-based record position, the field
1053	// and the reason; the batch id is attached only when it is itself non-empty,
1054	// valid UTF-8 text — never a U+FFFD substitution for a malformed id. A batch
1055	// id seen twice is reported as a *DuplicateIDError carrying both 1-based
1056	// positions, even when the two records are identical: Save persists records,
1057	// it never confirms duplicates or merges them. Text is checked verbatim —
1058	// no trimming, no case folding — and reg is never modified.
1059	func validateForSave(reg *Registry) error {
1060		seen := make(map[string]int, len(reg.Batches))
1061		for i, b := range reg.Batches {
1062			pos := i + 1
1063			batchID := safeBatchIDForError(b.Batch)
1064			// Save reports the first problem in batch, product, unit field
1065			// order, with a field's encoding problem ahead of its empty-string
1066			// problem — exactly the order inspectRecordText lists issues in.
1067			if issues := inspectRecordText(b.Batch, b.Product, b.Unit); len(issues) > 0 {
1068				issue := issues[0]
1069				if issue.kind == textEncoding {
1070					return &FormatError{Position: pos, Batch: batchID, Field: issue.field,
1071						Reason: "must be valid UTF-8 text: malformed bytes are rejected instead of being replaced with U+FFFD"}
1072				}
1073				return &FormatError{Position: pos, Batch: batchID, Field: issue.field, Reason: "must not be empty"}
1074			}
1075			if !quantityInRange(b.Quantity) {
1076				return &FormatError{Position: pos, Batch: batchID, Field: "quantity",
1077					Reason: fmt.Sprintf("must be between 1 and %d", MaxQuantity)}
1078			}
1079			if first, dup := seen[b.Batch]; dup {
1080				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
1081			}
1082			seen[b.Batch] = pos
1083		}
1084		return nil
1085	}
1086	
1087	// WriteTempContent and RenameTempFile are the two failure-prone steps of the
1088	// atomic save — writing the new content into the temporary file, and replacing
1089	// the target with it — kept behind package-level variables so the regression
1090	// tests (including the batch-import entry-point tests in the cmd/govflow
1091	// package) can make a chosen step of a real save fail deterministically, on the
1092	// save's actual target rather than a neighboring unusable path. Production
1093	// behavior is exactly the wrapped os operations; production code never swaps
1094	// them.
1095	var (
1096		WriteTempContent = func(f *os.File, data []byte) (int, error) { return f.Write(data) }
1097		RenameTempFile   = os.Rename
1098	)
1099	
1100	// resolveRegistryTarget returns the real file a save to path must replace,
1101	// resolved the same way the kernel resolves path for reads: every symbolic
1102	// link is chased — links on DIRECTORY components included — and every ".."
1103	// steps out of the directory it really leaves, not out of the link's own
1104	// parent name. The result is a cleaned path with no link or ".." component
1105	// naming exactly the file Load read, so the temporary file and the rename
1106	// land in the target's real directory (a relative path stays relative,
1107	// resolved against the process working directory as the input was).
1108	//
1109	// Physical resolution is what keeps read and save locations identical when a
1110	// directory link is followed by "..": with work/alias -> store/child, the
1111	// path work/alias/../batches.json means store/batches.json. Lexical cleaning
1112	// (filepath.Clean, filepath.Dir) collapses alias/.. to work and would save
1113	// next to the link — into an unrelated, possibly read-only directory.
1114	// Components missing from the filesystem (a first registration) are appended
1115	// verbatim onto the longest existing prefix, so creating a new file needs
1116	// write permission only in the directory that really holds it.
1117	//
1118	// A path that descends into a directory that does not exist and only then
1119	// climbs back with ".." — store/missing/../batches.json with no store/missing
1120	// — cannot reach any file the way the kernel resolves names, so it is an
1121	// error rather than a first registration: the save neither creates the
1122	// missing directory (which would turn an unresolvable path into a live one)
1123	// nor writes the lexically cleaned name (store/batches.json), which may be an
1124	// unrelated existing registry. A path that only creates new directories
1125	// without climbing back out (store/new/batches.json), or climbs ".." after a
1126	// prefix that really exists, is resolved and saved normally.
1127	//
1128	// A dangling symbolic link or a link loop — on the final component or on a
1129	// directory leading to it — is an error: the save must not create the target
1130	// or overwrite the link as if this were a first registration.
1131	func resolveRegistryTarget(path string) (string, error) {
1132		// Climb through components missing from the filesystem by stripping raw
1133		// path segments, never by lexical cleaning: filepath.Clean would collapse
1134		// "alias/.." against the link's own parent name before the kernel ever
1135		// resolves alias, sending the save at work/x.json instead of store/x.json.
1136		// os.Lstat resolves every component but the last exactly as the kernel
1137		// does, so each surviving prefix is checked with its real meaning.
1138		cur := path
1139		var tail []string
1140		for {
1141			info, err := os.Lstat(cur)
1142			if err == nil {
1143				// Refuse a ".." among the not-yet-existing components that climbs
1144				// back out of a directory which would first have to be created:
1145				// the user's path itself cannot name anything there, and creating
1146				// the directory would make a previously unresolvable path valid.
1147				if missing, escape := missingDirDotDotEscape(tail); escape {
1148					return "", errEscapeThroughMissingDir(missing)
1149				}
1150				// cur is the longest existing prefix. Resolve it physically: an
1151				// absolute link target, or a relative one resolved against the
1152				// link's own directory (never the process working directory), is
1153				// followed; a dangling link or a loop fails here and is reported
1154				// as an unusable symbolic link rather than a fresh-registry path.
1155				base, eerr := filepath.EvalSymlinks(cur)
1156				if eerr != nil {
1157					if info.Mode()&os.ModeSymlink != 0 {
1158						return "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", eerr)
1159					}
1160					return "", fmt.Errorf("cannot inspect registry path: %w", eerr)
1161				}
1162				// Append the not-yet-existing components verbatim: a first
1163				// registration needs write permission only in the real directory
1164				// that will hold the file, never in directories merely traversed.
1165				target := base
1166				for i := len(tail) - 1; i >= 0; i-- {
1167					target = filepath.Join(target, tail[i])
1168				}
1169				return filepath.Clean(target), nil
1170			}
1171			if !errors.Is(err, fs.ErrNotExist) {
1172				return "", fmt.Errorf("cannot inspect registry path: %w", err)
1173			}
1174			parent, base := rawParent(cur)
1175			tail = append(tail, base)
1176			if parent == cur {
1177				// A bare relative name with no existing prefix: it names a file
1178				// in the process working directory, just as a plain open would —
1179				// unless it climbs ".." out of a directory that does not exist.
1180				if missing, escape := missingDirDotDotEscape(tail); escape {
1181					return "", errEscapeThroughMissingDir(missing)
1182				}
1183				return filepath.Clean(path), nil
1184			}
1185			cur = parent
1186		}
1187	}
1188	
1189	// missingDirDotDotEscape inspects the raw components stripped while climbing
1190	// to the longest existing prefix. tail holds them from the registry file end
1191	// (tail[0] is the final, registry-file component) toward the existing prefix
1192	// (tail[len-1] sits next to it). A ".." that climbs out of a directory
1193	// descended into only within the not-yet-existing tail marks exactly the
1194	// unresolvable shape — store/missing/../batches.json — that must be refused:
1195	// the kernel cannot resolve the ".." until "missing" exists, and it never
1196	// legitimately exists on this path.
1197	//
1198	// The final component is the registry file name, never a directory descent,
1199	// so tail[0] is not counted. ".." steps matched by an equally non-existent
1200	// descent keep the lexical depth positive and do not cancel the violation:
1201	// the first ".." that leaves a missing directory is already fatal. The
1202	// returned name is the missing directory that ".." immediately tries to
1203	// leave. Symlinked or genuinely existing components never reach tail, so
1204	// this never trips over a physical ".." (as after work/alias -> store/child).
1205	func missingDirDotDotEscape(tail []string) (missing string, escape bool) {
1206		depth := 0
1207		lastMissing := ""
1208		// Walk from the existing-prefix side toward the file.
1209		for i := len(tail) - 1; i >= 1; i-- {
1210			switch tail[i] {
1211			case ".", "":
1212				// A "." (or the empty segment of a doubled separator) is a
1213				// lexical no-op even in the not-yet-existing tail.
1214			case "..":
1215				if depth > 0 {
1216					return lastMissing, true
1217				}
1218				depth--
1219			default:
1220				depth++
1221				lastMissing = tail[i]
1222			}
1223		}
1224		return "", false
1225	}
1226	
1227	// errEscapeThroughMissingDir is the refusal reason for a registry path that
1228	// descends into a non-existent directory and then climbs back with "..". The
1229	// Save wrapper adds the user-supplied path; the missing directory is named so
1230	// the user can see which component made the path unresolvable.
1231	func errEscapeThroughMissingDir(missing string) error {
1232		return fmt.Errorf(
1233			"the path descends through directory %s, which does not exist, and then climbs back with \"..\"; "+
1234				"such a path cannot reach an existing file and the missing directory is not created to make it valid, so the registry is not written",
1235			strconv.Quote(missing))
1236	}
1237	
1238	// rawParent splits path at its final separator without resolving "..", so the
1239	// caller can climb one raw component at a time and keep physical resolution of
1240	// any directory link in the surviving prefix.
1241	func rawParent(path string) (parent, base string) {
1242		i := strings.LastIndexByte(path, os.PathSeparator)
1243		if i < 0 {
1244			return path, path
1245		}
1246		return path[:i], path[i+1:]
1247	}
1248	
1249	// Save atomically writes reg to path, replacing the file only after the new
1250	// content is fully on disk so an existing registry stays usable on failure.
1251	// Records are serialized in their current order; the file is created with
1252	// 0644 permissions or, when replacing an existing file, with its permissions.
1253	//
1254	// When path reaches the registry through a symbolic link, the link's target
1255	// is the file replaced: the new content is prepared next to the target and
1256	// moved over it, so the link stays a link to the same target and the target
1257	// keeps its permissions, while reads through either the link or the real
1258	// path see the saved records. This holds for a link on the final component
1259	// and for a link on a DIRECTORY component, including a ".." that steps back
1260	// after it: with work/alias -> store/child, work/alias/../batches.json is
1261	// store/batches.json, and the save writes there even though the directory
1262	// containing the link (here work) is not writable — write access is needed
1263	// only in the target's real directory. A link whose target does not exist,
1264	// or a link loop, on the file or on a leading directory, rejects the save
1265	// with an error naming path — the target is never created and the link is
1266	// never replaced.
1267	//
1268	// A path that descends through a directory that does not exist and only then
1269	// climbs back with ".." (store/missing/../batches.json with store/missing
1270	// absent) is likewise rejected before anything is written: such a path
1271	// reaches no file the way the kernel resolves names, so the save neither
1272	// creates the missing directory — which would turn the unresolvable path into
1273	// a live one — nor writes the lexically cleaned name, where an unrelated
1274	// registry could be overwritten. A ".." after a directory that genuinely
1275	// exists, including the real target of a directory symlink, still resolves by
1276	// real directory relations, and a not-yet-existing parent that is never
1277	// climbed out of (store/new/batches.json) is created as on any first save.
1278	//
1279	// Every record must satisfy the same effective-value rules Load enforces, so
1280	// a registry saved successfully always reads back: batch, product and unit
1281	// must be non-empty valid UTF-8 text (kept verbatim — no trimming or case
1282	// folding, so whitespace-only text is ordinary non-empty text), quantity
1283	// must lie in 1..MaxQuantity, and batch ids must be unique under exact
1284	// byte-for-byte comparison, two identical records included. Any violation
1285	// rejects the whole save before anything is written: an existing target
1286	// keeps its bytes and modification time, a missing target stays missing and
1287	// no temporary file is left behind. A nil or empty Batches is a legal empty
1288	// registry and is written as "batches": [] without touching reg itself.
1289	func Save(path string, reg *Registry) error {
1290		if reg.Version != FormatVersion {
1291			return fmt.Errorf("cannot write registry format version %d", reg.Version)
1292		}
1293		if err := validateForSave(reg); err != nil {
1294			return fmt.Errorf("cannot save registry %q: %w", path, err)
1295		}
1296		target, err := resolveRegistryTarget(path)
1297		if err != nil {
1298			return fmt.Errorf("cannot save registry %q: %w", path, err)
1299		}
1300		mode := os.FileMode(0o644)
1301		if info, err := os.Stat(target); err == nil {
1302			mode = info.Mode().Perm()
1303		} else if !errors.Is(err, fs.ErrNotExist) {
1304			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
1305		}
1306	
1307		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
1308			return fmt.Errorf("cannot save registry %q: %w", path, err)
1309		}
1310	
1311		// Encode a shallow copy so a nil Batches marshals as [] (null would not
1312		// read back) without mutating the caller's registry.
1313		out := *reg
1314		if out.Batches == nil {
1315			out.Batches = []Batch{}
1316		}
1317		var buf bytes.Buffer
1318		enc := json.NewEncoder(&buf)
1319		enc.SetEscapeHTML(false)
1320		enc.SetIndent("", "  ")
1321		if err := enc.Encode(&out); err != nil {
1322			return fmt.Errorf("cannot encode registry %q: %w", path, err)
1323		}
1324	
1325		tmp, err := os.CreateTemp(filepath.Dir(target), ".govflow-registry-*.tmp")
1326		if err != nil {
1327			return fmt.Errorf("cannot save registry %q: %w", path, err)
1328		}
1329		tmpName := tmp.Name()
1330		abort := func(cause error) error {
1331			tmp.Close()
1332			os.Remove(tmpName)
1333			return fmt.Errorf("cannot save registry %q: %w", path, cause)
1334		}
1335		if _, err := WriteTempContent(tmp, buf.Bytes()); err != nil {
1336			return abort(err)
1337		}
1338		if err := tmp.Chmod(mode); err != nil {
1339			return abort(err)
1340		}
1341		if err := tmp.Sync(); err != nil {
1342			return abort(err)
1343		}
1344		if err := tmp.Close(); err != nil {
1345			os.Remove(tmpName)
1346			return fmt.Errorf("cannot save registry %q: %w", path, err)
1347		}
1348		if err := RenameTempFile(tmpName, target); err != nil {
1349			os.Remove(tmpName)
1350			return fmt.Errorf("cannot save registry %q: %w", path, err)
1351		}
1352		return nil
1353	}
1354

