204		assertLinkIntact(t, aliasPath, filepath.Join("..", "store", "child"))
205		assertNoLeftoverTempFiles(t, root)
206		// The read-only directory must contain only what it started with.
207		entries, err := os.ReadDir(workDir)
208		if err != nil {
209			t.Fatal(err)
210		}
211		for _, e := range entries {
212			if e.Name() != "alias" && e.Name() != "batches.json" {
213				t.Fatalf("save created %q in the read-only link directory", e.Name())
214			}
215		}
216		_ = decoyPath
217	}
218	
219	// The atomic rename — the step that actually chooses which file is replaced —
220	// must target the real store/batches.json, never the same-named decoy beside
221	// the link. This works under every account, root included, because it
222	// observes Save's own resolved target.
223	func TestSaveThroughDirectorySymlinkDotDotRenamesRealFile(t *testing.T) {
