1	package batchreg
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// This file is the regression net for using a registry through a symbolic
14	// link. The rule under guard: a save addressed at a link must land in the
15	// file the link points at — the link stays a link to the same target, the
16	// target keeps its permissions, and reads through either path see the same
17	// records — while a link whose target cannot be resolved (dangling or
18	// looping) rejects the operation instead of being treated as a first
19	// registration.
20	
21	// symlinkFixtureRegistry is the registry content every linked-target fixture
22	// starts from.
23	const symlinkFixtureRegistry = `{"version":1,"batches":[{"batch":"OLD-1","product":"P-1","quantity":10,"unit":"kg"}]}`
24	
25	// symlinkFixtureMode is a distinctive permission set for the target file, so
26	// a save that recreates the file with default permissions is observable.
27	const symlinkFixtureMode = os.FileMode(0o640)
28	
29	// setupLinkedRegistry writes the fixture registry to targetPath with
30	// symlinkFixtureMode permissions and points a symbolic link at it. linkTarget
31	// is the exact text stored in the link, absolute or relative to the link's
32	// directory. It returns the link path and the original target bytes.
33	func setupLinkedRegistry(t *testing.T, targetPath, linkPath, linkTarget string) (originalBytes []byte) {
34		t.Helper()
35		writeRegistry(t, targetPath, symlinkFixtureRegistry)
36		if err := os.Chmod(targetPath, symlinkFixtureMode); err != nil {
37			t.Fatal(err)
38		}
39		if err := os.MkdirAll(filepath.Dir(linkPath), 0o755); err != nil {
40			t.Fatal(err)
41		}
42		if err := os.Symlink(linkTarget, linkPath); err != nil {
43			t.Fatal(err)
44		}
45		originalBytes, err := os.ReadFile(targetPath)
46		if err != nil {
47			t.Fatal(err)
48		}
49		return originalBytes
50	}
51	
52	// assertLinkIntact fails unless path is still a symbolic link storing exactly
53	// the link target text wantTarget.
54	func assertLinkIntact(t *testing.T, path, wantTarget string) {
55		t.Helper()
56		info, err := os.Lstat(path)
57		if err != nil {
58			t.Fatalf("the link must still exist: %v", err)
59		}
60		if info.Mode()&os.ModeSymlink == 0 {
61			t.Fatalf("%s must still be a symbolic link, got mode %v", path, info.Mode())
62		}
63		target, err := os.Readlink(path)
64		if err != nil {
65			t.Fatal(err)
66		}
67		if target != wantTarget {
68			t.Fatalf("link target = %q, want unchanged %q", target, wantTarget)
69		}
70	}
71	
72	// TestSaveThroughSymlinkWritesTarget covers the accepted link shapes —
73	// absolute target, relative target, target in a different directory — and
74	// checks the whole contract: the new content lands in the target file, the
75	// link survives as a link to the same target, the target keeps its
76	// permissions, and both paths read back the same records in order.
77	func TestSaveThroughSymlinkWritesTarget(t *testing.T) {
78		cases := []struct {
79			name       string
80			linkPath   func(root string) string
81			linkTarget func(root, targetPath string) string
82		}{
83			{
84				"absolute target, link beside target",
85				func(root string) string { return filepath.Join(root, "link.json") },
86				func(root, targetPath string) string { return targetPath },
87			},
88			{
89				"relative target, link beside target",
90				func(root string) string { return filepath.Join(root, "link.json") },
91				func(root, targetPath string) string { return "real-registry.json" },
92			},
93			{
94				"relative target, link in another directory",
95				func(root string) string { return filepath.Join(root, "links", "deep", "link.json") },
96				func(root, targetPath string) string {
97					return filepath.Join("..", "..", "real-registry.json")
98				},
99			},
100			{
101				"absolute target, link in another directory",
102				func(root string) string { return filepath.Join(root, "elsewhere", "link.json") },
103				func(root, targetPath string) string { return targetPath },
104			},
105		}
106		for _, tc := range cases {
107			t.Run(tc.name, func(t *testing.T) {
108				root := t.TempDir()
109				targetPath := filepath.Join(root, "real-registry.json")
110				linkPath := tc.linkPath(root)
111				linkTarget := tc.linkTarget(root, targetPath)
112				setupLinkedRegistry(t, targetPath, linkPath, linkTarget)
113	
114				reg, existed, err := Load(linkPath)
115				if err != nil || !existed {
116					t.Fatalf("reading through the link must load the target: existed=%v err=%v", existed, err)
117				}
118				if len(reg.Batches) != 1 || reg.Batches[0].Batch != "OLD-1" {
119					t.Fatalf("reading through the link must see the target records: %+v", reg.Batches)
120				}
121				if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
122					t.Fatal(err)
123				}
124				if err := Save(linkPath, reg); err != nil {
125					t.Fatalf("saving through the link must succeed: %v", err)
126				}
127	
128				assertLinkIntact(t, linkPath, linkTarget)
129				info, err := os.Stat(targetPath)
130				if err != nil {
131					t.Fatal(err)
132				}
133				if info.Mode().Perm() != symlinkFixtureMode {
134					t.Fatalf("target permissions = %v, want preserved %v", info.Mode().Perm(), symlinkFixtureMode)
135				}
136	
137				want := []Batch{
138					saveBatch("OLD-1", "P-1", 10, "kg"),
139					saveBatch("NEW-1", "P-9", 5, "box"),
140				}
141				viaTarget, existed, err := Load(targetPath)
142				if err != nil || !existed {
143					t.Fatalf("target must load: existed=%v err=%v", existed, err)
144				}
145				assertBatchesEqual(t, viaTarget.Batches, want)
146				viaLink, existed, err := Load(linkPath)
147				if err != nil || !existed {
148					t.Fatalf("link must load: existed=%v err=%v", existed, err)
149				}
150				assertBatchesEqual(t, viaLink.Batches, want)
151				assertNoLeftoverTempFiles(t, root)
152			})
153		}
154	}
155	
156	// A relative link target is resolved against the directory holding the link,
157	// never against the process working directory: saving through the link from
158	// an unrelated working directory must still update the one registry the link
159	// points at.
160	func TestSaveThroughRelativeSymlinkIgnoresWorkingDirectory(t *testing.T) {
161		root := t.TempDir()
162		targetPath := filepath.Join(root, "regdir", "registry.json")
163		linkPath := filepath.Join(root, "links", "registry-link.json")
164		setupLinkedRegistry(t, targetPath, linkPath, filepath.Join("..", "regdir", "registry.json"))
165	
166		// A decoy registry with the same relative path under the working
167		// directory: a save resolving the link against the working directory
168		// would land here instead of in the real target.
169		workDir := t.TempDir()
170		decoyPath := filepath.Join(workDir, "regdir", "registry.json")
171		writeRegistry(t, decoyPath, `{"version":1,"batches":[{"batch":"DECOY","product":"P","quantity":1,"unit":"kg"}]}`)
172		decoyBytes, err := os.ReadFile(decoyPath)
173		if err != nil {
174			t.Fatal(err)
175		}
176		t.Chdir(workDir)
177	
178		reg, existed, err := Load(linkPath)
179		if err != nil || !existed {
180			t.Fatalf("reading through the link must load the target: existed=%v err=%v", existed, err)
181		}
182		if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
183			t.Fatal(err)
184		}
185		if err := Save(linkPath, reg); err != nil {
186			t.Fatalf("saving through the link must succeed: %v", err)
187		}
188	
189		loaded, existed, err := Load(targetPath)
190		if err != nil || !existed {
191			t.Fatalf("target must load: existed=%v err=%v", existed, err)
192		}
193		assertBatchesEqual(t, loaded.Batches, []Batch{
194			saveBatch("OLD-1", "P-1", 10, "kg"),
195			saveBatch("NEW-1", "P-9", 5, "box"),
196		})
197		after, err := os.ReadFile(decoyPath)
198		if err != nil {
199			t.Fatal(err)
200		}
201		if !bytes.Equal(after, decoyBytes) {
202			t.Fatalf("the decoy registry under the working directory must stay untouched:\nbefore %s\nafter  %s", decoyBytes, after)
203		}
204		assertLinkIntact(t, linkPath, filepath.Join("..", "regdir", "registry.json"))
205	}
206	
207	// A link whose target does not exist is not a first registration: Load
208	// rejects it with an error naming the link path the user passed and the
209	// reason, and neither the target nor any stand-in file is created.
210	func TestLoadRejectsDanglingSymlink(t *testing.T) {
211		dir := t.TempDir()
212		linkPath := filepath.Join(dir, "link.json")
213		missingTarget := filepath.Join(dir, "missing.json")
214		if err := os.Symlink(missingTarget, linkPath); err != nil {
215			t.Fatal(err)
216		}
217	
218		reg, existed, err := Load(linkPath)
219		if err == nil {
220			t.Fatalf("Load must reject a dangling link, got reg=%+v existed=%v", reg, existed)
221		}
222		if !existed {
223			t.Errorf("a dangling link must not signal a fresh registry: existed=%v", existed)
224		}
225		msg := err.Error()
226		if !strings.Contains(msg, linkPath) {
227			t.Errorf("error %q must name the registry path the user passed", msg)
228		}
229		if !strings.Contains(msg, "symbolic link") || !strings.Contains(msg, "does not exist") {
230			t.Errorf("error %q must state the link target does not exist", msg)
231		}
232		assertLinkIntact(t, linkPath, missingTarget)
233		if _, statErr := os.Stat(missingTarget); !os.IsNotExist(statErr) {
234			t.Errorf("the missing target must not be created, stat err=%v", statErr)
235		}
236	}
237	
238	// Saving to a dangling link is rejected the same way: the error names the
239	// user's registry path, the link is left exactly as it was, the target is
240	// not created and no temporary file survives.
241	func TestSaveRejectsDanglingSymlink(t *testing.T) {
242		dir := t.TempDir()
243		linkPath := filepath.Join(dir, "link.json")
244		missingTarget := filepath.Join(dir, "missing.json")
245		if err := os.Symlink(missingTarget, linkPath); err != nil {
246			t.Fatal(err)
247		}
248	
249		reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("B1", "P1", 1, "kg")}}
250		err := Save(linkPath, reg)
251		if err == nil {
252			t.Fatal("Save must reject a dangling link")
253		}
254		msg := err.Error()
255		if !strings.Contains(msg, linkPath) {
256			t.Errorf("error %q must name the registry path the user passed", msg)
257		}
258		if !strings.Contains(msg, "symbolic link") {
259			t.Errorf("error %q must state the path is an unresolvable symbolic link", msg)
260		}
261		assertLinkIntact(t, linkPath, missingTarget)
262		if _, statErr := os.Stat(missingTarget); !os.IsNotExist(statErr) {
263			t.Errorf("the missing target must not be created, stat err=%v", statErr)
264		}
265		assertNoLeftoverTempFiles(t, dir)
266	}
267	
268	// A chain of links forming a loop has no determinable target: both Load and
269	// Save reject it with an error naming the user's registry path, and the
270	// links are left untouched.
271	func TestLoadAndSaveRejectSymlinkLoop(t *testing.T) {
272		dir := t.TempDir()
273		linkA := filepath.Join(dir, "a.json")
274		linkB := filepath.Join(dir, "b.json")
275		if err := os.Symlink(linkB, linkA); err != nil {
276			t.Fatal(err)
277		}
278		if err := os.Symlink(linkA, linkB); err != nil {
279			t.Fatal(err)
280		}
281	
282		_, _, loadErr := Load(linkA)
283		if loadErr == nil {
284			t.Fatal("Load must reject a link loop")
285		}
286		if !strings.Contains(loadErr.Error(), linkA) {
287			t.Errorf("load error %q must name the registry path the user passed", loadErr.Error())
288		}
289	
290		reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("B1", "P1", 1, "kg")}}
291		saveErr := Save(linkA, reg)
292		if saveErr == nil {
293			t.Fatal("Save must reject a link loop")
294		}
295		if !strings.Contains(saveErr.Error(), linkA) {
296			t.Errorf("save error %q must name the registry path the user passed", saveErr.Error())
297		}
298		assertLinkIntact(t, linkA, linkB)
299		assertLinkIntact(t, linkB, linkA)
300		assertNoLeftoverTempFiles(t, dir)
301	}
302	
303	// A save failing midway through a link keeps the linked registry exactly as
304	// it was: the target's bytes and modification time are untouched and the
305	// link survives, just as for a direct path.
306	func TestSaveFailureThroughSymlinkKeepsTargetIntact(t *testing.T) {
307		root := t.TempDir()
308		targetPath := filepath.Join(root, "real-registry.json")
309		linkPath := filepath.Join(root, "link.json")
310		originalBytes := setupLinkedRegistry(t, targetPath, linkPath, targetPath)
311		pinned := time.Date(2010, time.March, 4, 5, 6, 7, 0, time.UTC)
312		if err := os.Chtimes(targetPath, pinned, pinned); err != nil {
313			t.Fatal(err)
314		}
315	
316		cause := errors.New("injected write failure through link")
317		old := WriteTempContent
318		WriteTempContent = func(f *os.File, data []byte) (int, error) {
319			half := len(data) / 2
320			if _, err := f.Write(data[:half]); err != nil {
321				return 0, err
322			}
323			return half, cause
324		}
325		t.Cleanup(func() { WriteTempContent = old })
326	
327		reg, existed, err := Load(linkPath)
328		if err != nil || !existed {
329			t.Fatalf("fixture must load through the link: existed=%v err=%v", existed, err)
330		}
331		if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
332			t.Fatal(err)
333		}
334		err = Save(linkPath, reg)
335		if err == nil {
336			t.Fatal("Save must report the injected failure")
337		}
338		if !errors.Is(err, cause) {
339			t.Errorf("error %v must carry the failure cause %v", err, cause)
340		}
341		if !strings.Contains(err.Error(), linkPath) {
342			t.Errorf("error %q must name the registry path the user passed %q", err.Error(), linkPath)
343		}
344	
345		info, err := os.Stat(targetPath)
346		if err != nil {
347			t.Fatal(err)
348		}
349		if !info.ModTime().Equal(pinned) {
350			t.Errorf("failed save touched the target's modification time: got %v, want %v", info.ModTime(), pinned)
351		}
352		after, err := os.ReadFile(targetPath)
353		if err != nil {
354			t.Fatal(err)
355		}
356		if !bytes.Equal(after, originalBytes) {
357			t.Fatalf("failed save changed the target bytes:\nbefore %s\nafter  %s", originalBytes, after)
358		}
359		assertLinkIntact(t, linkPath, targetPath)
360		assertNoLeftoverTempFiles(t, root)
361	}
