20	// assertStillSymlink fails unless path is still a symbolic link storing
21	// exactly wantTarget.
22	func assertStillSymlink(t *testing.T, path, wantTarget string) {
23		t.Helper()
24		info, err := os.Lstat(path)
25		if err != nil {
26			t.Fatalf("the link must still exist: %v", err)
27		}
28		if info.Mode()&os.ModeSymlink == 0 {
29			t.Fatalf("%s must still be a symbolic link, got mode %v", path, info.Mode())
30		}
31		target, err := os.Readlink(path)
32		if err != nil {
33			t.Fatal(err)
34		}
35		if target != wantTarget {
36			t.Fatalf("link target = %q, want unchanged %q", target, wantTarget)
37		}
38	}
