40	// setupLinkedCLIRegistry writes content to targetPath with the given
41	// permissions and points a symbolic link at it, returning the link path.
42	func setupLinkedCLIRegistry(t *testing.T, targetPath, linkPath, linkTarget, content string, mode os.FileMode) {
43		t.Helper()
44		writeFile(t, targetPath, content)
45		if err := os.Chmod(targetPath, mode); err != nil {
