56	// Registering a new batch through a link appends it to the linked registry:
57	// the target file gains the record after the existing ones, the link is
58	// still a link to the same target, the target keeps its permissions, and
59	// reading back through either path sees the same two batches.
60	func TestBatchRegisterThroughSymlinkSavesToTarget(t *testing.T) {
61		cases := []struct {
62			name       string
63			linkPath   func(root string) string
64			linkTarget func(root, targetPath string) string
65		}{
