69				func(root, targetPath string) string { return targetPath },
70			},
71			{
72				"relative target, link in another directory",
73				func(root string) string { return filepath.Join(root, "links", "link.json") },
74				func(root, targetPath string) string { return filepath.Join("..", "real.json") },
75			},
76		}
77		for _, tc := range cases {
78			t.Run(tc.name, func(t *testing.T) {
79				root := t.TempDir()
80				targetPath := filepath.Join(root, "real.json")
81				linkPath := tc.linkPath(root)
82				linkTarget := tc.linkTarget(root, targetPath)
83				setupLinkedCLIRegistry(t, targetPath, linkPath, linkTarget,
84					`{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`, 0o640)
