12	// End-to-end regression for a --registry that reaches the file through a
13	// DIRECTORY symbolic link followed by "..": work/alias -> store/child makes
14	// work/alias/../batches.json name store/batches.json. Both commands must read
15	// the real registry and save back to that same real file, appending new
16	// batches after the existing ones, even though the directory holding the link
17	// is not writable. An unrelated work/batches.json and the link itself must be
18	// left exactly as they were; nothing (file, temporary file or directory) may
19	// be created under work.
20	
21	// setupDirLinkCLIFixture builds the store/work layout: a real registry with
22	// one record, a decoy same-named registry beside the link, and the directory
23	// link. It returns the raw user path work/alias/../batches.json (assembled by
24	// concatenation so the link segment and ".." survive lexical cleaning), the
25	// real and decoy registry paths, the link path and the link target text.
26	func setupDirLinkCLIFixture(t *testing.T, realContent string) (userPath, realPath, decoyPath, aliasPath, aliasTarget string) {
27		t.Helper()
28		root := t.TempDir()
29		storeDir := filepath.Join(root, "store")
30		if err := os.MkdirAll(filepath.Join(storeDir, "child"), 0o755); err != nil {
31			t.Fatal(err)
32		}
33		workDir := filepath.Join(root, "work")
34		if err := os.MkdirAll(workDir, 0o755); err != nil {
35			t.Fatal(err)
36		}
37		realPath = filepath.Join(storeDir, "batches.json")
38		writeFile(t, realPath, realContent)
39		decoyPath = filepath.Join(workDir, "batches.json")
40		writeFile(t, decoyPath, `{"version":1,"batches":[{"batch":"DECOY","product":"P-0","quantity":1,"unit":"m"}]}`)
41		aliasTarget = filepath.Join("..", "store", "child")
42		aliasPath = filepath.Join(workDir, "alias")
43		if err := os.Symlink(aliasTarget, aliasPath); err != nil {
44			t.Fatal(err)
45		}
46		userPath = aliasPath + string(os.PathSeparator) + ".." + string(os.PathSeparator) + "batches.json"
47		return userPath, realPath, decoyPath, aliasPath, aliasTarget
48	}
49	
50	// assertOnlyLinkAndDecoy fails if anything besides the directory link and the
51	// pre-existing decoy exists in the link's own directory.
52	func assertOnlyLinkAndDecoy(t *testing.T, linkDir string) {
53		t.Helper()
54		entries, err := os.ReadDir(linkDir)
55		if err != nil {
56			t.Fatal(err)
57		}
58		for _, e := range entries {
59			if e.Name() != "alias" && e.Name() != "batches.json" {
60				t.Fatalf("the command created %q next to the directory link", e.Name())
61			}
62		}
63	}
64	
65	// batchIDs reads the batch ids of a registry in stored order.
66	func batchIDs(t *testing.T, path string) []string {
67		t.Helper()
68		data, err := os.ReadFile(path)
69		if err != nil {
70			t.Fatal(err)
71		}
72		var stored struct {
73			Batches []struct {
74				Batch string `json:"batch"`
75			} `json:"batches"`
76		}
77		if err := json.Unmarshal(data, &stored); err != nil {
78			t.Fatalf("registry %s is not valid JSON: %v (%s)", path, err, data)
79		}
80		ids := make([]string, len(stored.Batches))
81		for i, b := range stored.Batches {
82			ids[i] = b.Batch
83		}
84		return ids
85	}
86	
87	// batch-register through work/alias/../batches.json appends the new batch to
88	// the real store/batches.json: stdout is the normal "created" JSON, the old
89	// record keeps its place, the real file and the user path read identically,
90	// the decoy and the link are untouched and nothing appears under work.
91	func TestBatchRegisterThroughDirectorySymlinkDotDotSavesRealFile(t *testing.T) {
92		userPath, realPath, decoyPath, aliasPath, aliasTarget := setupDirLinkCLIFixture(t,
93			`{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`)
94		decoy, pinned := pinRegistry(t, decoyPath)
95	
96		var stdout bytes.Buffer
97		if err := runBatchRegister([]string{
98			"--registry", userPath,
99			"--batch", "NEW-1", "--product", "P-9", "--quantity", "5", "--unit", "box",
100		}, &stdout); err != nil {
101			t.Fatalf("registering through the directory link must succeed: %v", err)
102		}
103		var out struct {
104			Batch  string `json:"batch"`
105			Status string `json:"status"`
106		}
107		if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
108			t.Fatalf("stdout is not the expected JSON: %v (%q)", err, stdout.String())
109		}
110		if out.Batch != "NEW-1" || out.Status != "created" {
111			t.Fatalf("stdout = %+v, want NEW-1/created", out)
112		}
113	
114		want := []string{"OLD", "NEW-1"}
115		if got := batchIDs(t, realPath); strings.Join(got, ",") != strings.Join(want, ",") {
116			t.Fatalf("real registry = %v, want %v (old order kept, new appended)", got, want)
117		}
118		// Reading through the user-given path must show exactly the real file.
119		if got := batchIDs(t, userPath); strings.Join(got, ",") != strings.Join(want, ",") {
120			t.Fatalf("registry read through the user path = %v, want %v", got, want)
121		}
122		assertRegistryUntouched(t, decoyPath, decoy, pinned)
123		assertStillSymlink(t, aliasPath, aliasTarget)
124		assertOnlyLinkAndDecoy(t, filepath.Dir(aliasPath))
125	}
126	
127	// batch-import through the directory link saves every new batch to the real
128	// registry and reports statuses in manifest order exactly as for a direct
129	// path; the decoy and link are untouched.
130	func TestBatchImportThroughDirectorySymlinkDotDotSavesRealFile(t *testing.T) {
131		userPath, realPath, decoyPath, aliasPath, aliasTarget := setupDirLinkCLIFixture(t,
132			`{"version":1,"batches":[{"batch":"B1","product":"P-7","quantity":120,"unit":"kg"}]}`)
133		manifest := filepath.Join(filepath.Dir(filepath.Dir(aliasPath)), "in.json")
134		writeFile(t, manifest, `[
135	  {"batch": "B1", "product": "P-7", "quantity": 120, "unit": "kg"},
136	  {"batch": "B2", "product": "P-8", "quantity": 1, "unit": "box"}
137	]`)
138		decoy, pinned := pinRegistry(t, decoyPath)
139	
140		var stdout bytes.Buffer
141		if err := runBatchImport([]string{"--registry", userPath, "--input", manifest}, &stdout); err != nil {
142			t.Fatalf("importing through the directory link must succeed: %v", err)
143		}
144		var out importOutput
145		if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
146			t.Fatalf("stdout is not the expected JSON: %v (%q)", err, stdout.String())
147		}
148		if len(out.Results) != 2 ||
149			out.Results[0].Batch != "B1" || out.Results[0].Status != "duplicate" ||
150			out.Results[1].Batch != "B2" || out.Results[1].Status != "created" {
151			t.Fatalf("results = %+v, want B1 duplicate then B2 created in manifest order", out.Results)
152		}
153		if got := batchIDs(t, realPath); strings.Join(got, ",") != "B1,B2" {
154			t.Fatalf("real registry = %v, want B1 then B2", got)
155		}
156		if got := batchIDs(t, userPath); strings.Join(got, ",") != "B1,B2" {
157			t.Fatalf("user-path registry = %v, want B1 then B2", got)
158		}
159		assertRegistryUntouched(t, decoyPath, decoy, pinned)
160		assertStillSymlink(t, aliasPath, aliasTarget)
161		assertOnlyLinkAndDecoy(t, filepath.Dir(aliasPath))
162	}
163	
164	// Making work (the directory holding the link) read-and-execute-only must not
165	// block either command: the save prepares its temporary file in the real
166	// target directory, so write access beside the link is never needed. Skipped
167	// under root, which bypasses directory permission bits.
168	func TestBatchCommandsThroughDirectorySymlinkDotDotNeedNoWriteInLinkDirectory(t *testing.T) {
169		if os.Geteuid() == 0 {
170			t.Skip("root bypasses directory write permission bits")
171		}
172		for _, command := range []string{"batch-register", "batch-import"} {
173			t.Run(command, func(t *testing.T) {
174				userPath, realPath, _, aliasPath, aliasTarget := setupDirLinkCLIFixture(t,
175					`{"version":1,"batches":[{"batch":"B1","product":"P-7","quantity":120,"unit":"kg"}]}`)
176				workDir := filepath.Dir(aliasPath)
177				manifest := filepath.Join(filepath.Dir(workDir), "in.json")
178				writeFile(t, manifest, `[{"batch":"B2","product":"P-8","quantity":1,"unit":"box"}]`)
179				if err := os.Chmod(workDir, 0o555); err != nil {
180					t.Fatal(err)
181				}
182				t.Cleanup(func() { _ = os.Chmod(workDir, 0o755) })
183	
184				var stdout bytes.Buffer
185				var err error
186				if command == "batch-register" {
187					err = runBatchRegister([]string{
188						"--registry", userPath,
189						"--batch", "B2", "--product", "P-8", "--quantity", "1", "--unit", "box",
190					}, &stdout)
191				} else {
192					err = runBatchImport([]string{"--registry", userPath, "--input", manifest}, &stdout)
193				}
194				if err != nil {
195					t.Fatalf("a read-only link directory must not block %s: %v", command, err)
196				}
197				if stdout.Len() == 0 {
198					t.Fatal("stdout must carry the normal success JSON")
199				}
200				if got := batchIDs(t, realPath); strings.Join(got, ",") != "B1,B2" {
201					t.Fatalf("real registry = %v, want B1 then B2", got)
202				}
203				if got := batchIDs(t, userPath); strings.Join(got, ",") != "B1,B2" {
204					t.Fatalf("user-path registry = %v, want B1 then B2", got)
205				}
206				assertStillSymlink(t, aliasPath, aliasTarget)
207				assertOnlyLinkAndDecoy(t, workDir)
208			})
209		}
210	}
211	
212	// When the REAL target directory is not writable, both commands must reject
213	// the operation like any save failure: an error naming the user-supplied
214	// registry path and the reason, the real registry left byte-for-byte and
215	// timestamp-for-timestamp, the decoy and link untouched and no file created
216	// under work. Skipped under root, which bypasses directory permission bits.
217	func TestBatchCommandsThroughDirectorySymlinkDotDotFailWhenRealDirectoryUnwritable(t *testing.T) {
218		if os.Geteuid() == 0 {
219			t.Skip("root bypasses directory write permission bits")
220		}
