// A loop of directory links likewise has no resolvable target.
func TestLoadRejectsDirectorySymlinkLoop(t *testing.T) {
	root := t.TempDir()
	workDir := filepath.Join(root, "work")
	if err := os.MkdirAll(workDir, 0o755); err != nil {
		t.Fatal(err)
	}
